arguments.command:
cd /workspace; sqlite3 -header data/northline.sqlite <<'EOF'
.tables
select * from markets;
select phase, status, randomisation_unit, boost_share_target, min(week_start), max(week_start), count(*), count(distinct market_id) from experiment_config group by 1,2,3,4;
select * from ops_events;
select min(placed_at), max(placed_at), count(*) from orders;
select order_channel, status, count(*) from orders group by 1,2;
select arm, count(*) from experiment_assignment group by 1;
select experiment_id, count(*) from experiment_assignment group by 1;
select * from market_week_baseline limit 5;
select min(week_start),max(week_start),count(*) from market_week_baseline;
select * from incentive_ledger limit 5;
select min(week_start),max(week_start),count(*) from incentive_ledger;
select min(shift_date),max(shift_date),count(*) from courier_shifts;
select placed_at from orders limit 5;
EOF

