arguments.command:
cd /workspace; python /tmp/q.py <<'EOF'
select c.market_id, c.boost_share_target p1, c2.status p2 from experiment_config c left join (select distinct market_id, status from experiment_config where phase='phase2_order_randomised') c2 using(market_id) where c.phase='phase1_soak' and c.week_start='2026-05-04' order by 2,1;
select o.order_channel, o.status, a.arm, count(*) from orders o join experiment_assignment a using(order_id) group by 1,2,3;
select count(*) from orders o join zones z using(zone_id) left join experiment_assignment a using(order_id) where o.placed_at>='2026-06-01' and z.market_id in (select market_id from experiment_config where status='running' and phase='phase2_order_randomised') and a.order_id is null;
select min(o.placed_at), max(o.placed_at) from orders o join experiment_assignment a using(order_id);
select count(*) from zones; select count(distinct zone_id) from orders; select count(*) from orders o left join zones z using(zone_id) where z.zone_id is null;
select market_id, count(*) from zones group by 1;
select count(*), count(distinct shift_id), count(distinct courier_id||market_id||shift_date||hour_start) from courier_shifts;
select min(online_minutes), max(online_minutes) from courier_shifts;
select count(*) from orders where status='delivered' and (delivered_after_min is null or promised_minutes is null);
select distinct promised_minutes from orders limit 20;
select count(*) from orders where order_id in (select order_id from orders group by order_id having count(*)>1)
EOF

